    {"slot": "what_settles_it", "text": "A declared price per point of pass rate, or a minimum acceptable pass rate. Either one picks the step on the frontier."}
  ],
  "claims": [
    {
      "id": "c1",
      "text": "Cost buys pass rate with sharply diminishing returns: each Nano-XS step up is cheap, and the last steps cost thousands a month per point.",
      "weight": "lead",
      "evidence": [{
        "block": "table",
        "query": {"source": "prices", "aspect": "", "measures": ["pass_rate"], "arms": [], "strata": [], "limit": 0, "transform": "none", "small_multiples_by": "none"},
        "caption": "Frontier steps with the monthly cost of each added point. Figures are unpaired point estimates from overall means; no interval is stated."
      }],
      "caveats": ["nothing_declared"]
    },
    {
      "id": "c2",
      "text": "Of the options measured, a few sit on the frontier and the rest are beaten on both cost and pass rate by a neighbour.",
      "weight": "support",
      "evidence": [{
        "block": "scatter_frontier",
        "query": {"source": "measures", "aspect": "", "measures": ["cost_per_1k", "pass_rate"], "arms": [], "strata": [], "limit": 0, "transform": "none", "small_multiples_by": "none"},
        "caption": "Cost per 1k calls (log axis) against pass rate for every arm, as one point estimate each."
      }],
      "caveats": ["best_of_n"]
    },
    {
      "id": "c3",
      "text": "The model matters most at low reasoning: Nano-XS trails Atlas-M clearly, while Brisk-S is within about a point of Atlas-M once reasoning is on.",
      "weight": "support",
      "evidence": [{
        "block": "table",
        "query": {"source": "levers", "aspect": "", "measures": ["pass_rate"], "arms": [], "strata": [], "limit": 12, "transform": "none", "small_multiples_by": "none"},
        "caption": "Model effects between arms that differ in the model alone, with 95% independent intervals; no pairing, so intervals read wide."
      }],
      "caveats": ["no_control"]
    }
  ],
  "explore": [
    {"control": "Price of one point of pass rate, per month", "binds": "Which frontier step is best", "outcome": "The best step moves up the frontier as a point is worth more; the bands are in the where_it_flips entry, from {price.nano-xs.off.r0.nano-xs.off.r1.pass_rate.monthly_per_point} to {price.brisk-s.high.r1.atlas-m.high.r1.pass_rate.monthly_per_point}."}
  ],
  "omitted": [
    {"what": "Every non-frontier arm's full table, and the remaining lever effects", "why": "None changes the trade, and they sit in the appendix."},
    {"what": "A hybrid routing mix", "why": "Nobody ran it, so no key states its cost or gain."},
    {"what": "Calls per task, extra calls and outcome measures", "why": "They describe the retry mechanism and do not change the trade."},
    {"what": "Latency for every arm", "why": "No budget was declared, and one arm's tail is named in Watch."}
  ],
  "next": [
    {"text": "The owner declares a price per point of pass rate, or a floor.", "settles": "Which frontier step to ship, with no more runs."},
    {"text": "Re-run the leading frontier options on fresh cases, with a control named.", "settles": "Whether the lean's pass rate holds after best-of-many selection, and gives paired intervals."},
    {"text": "Declare a latency budget and read p95 for the frontier arms.", "settles": "Whether the cheap Nano-XS steps are usable."}
  ],
  "method": [
    {"term": "Design", "text": "A crossed sweep of three models, three reasoning levels and two retry settings, so {n_candidates} arms, each on the same number of cases per the scoreboard.", "caveats": ["no_control"]},
    {"term": "Pass rate", "text": "Each arm's overall pass share. The snapshot does not say what makes a trial pass beyond that, and no judge was involved."},
    {"term": "Cost", "text": "Cost per 1k calls as measured. Monthly figures use a volume of {meta.volume_per_month} a month, a count the input does not name. The provider routing is not named."},
    {"term": "Intervals", "text": "Lever intervals are 95% and independent, which reads wider than a paired one. Price steps carry no interval."},
    {"term": "Not compared", "text": "No arm was declared a control, and no gate, floor or margin was set, so code made no dominance call.", "caveats": ["nothing_declared"]}
  ]
}
